#!/bin/bash
# Codex scene prompts: Ferrari FZ8004U 504 + Varilux XR gift set. Each run costs ChatGPT quota.
cd /c/timeoptic-content
K=kits/2026-11-11_ferrari-varilux-gift
P=$K/photos
REFS="-i $P/S__27377686.jpg -i $P/S__27377683.jpg -i $P/S__27377703.jpg -i $P/S__27377705.jpg -i $P/S__27377706.jpg -i $P/S__27377707.jpg"
KEEP="The attached photos show the real products; reproduce them exactly. (1) Optical eyeglasses: rectangular matte black front, clear lenses, matte black temples ending in bright yellow rubber tips, a small yellow prancing-horse shield on the outer temple near the hinge; same shape, proportions and colors, do not redesign or add parts. (2) A black quilted padded drawstring pouch with a short black cord loop at the top and one small yellow Ferrari shield printed in the centre. (3) A dark navy booklet with 'Varilux XR series' in white at the top left and the white essilor eye logo at the bottom right. (4) A blue gradient card with 'Varilux XR series' at the top left and the essilor eye logo at the bottom right. (5) A dark navy card with a gold scalloped seal reading 'WEARER'S ADAPTATION / essilor / PROGRESSIVE LENS WARRANTY'. Keep the printed graphics on these items as in the photos; never invent other text or logos. The glasses are the hero, sharp, in focus and physically resting on the surface with a realistic contact shadow (no floating parts)."
STYLE="Square 1:1 luxury eyewear advertising photograph, cinematic, dark and moody, shot on a medium-format camera, shallow depth of field. No added text, headlines or watermarks anywhere. Leave calm dark negative space in the top 18% and bottom 14% of the frame for a logo overlay."
run () { codex exec -m gpt-5.6-luna -c model_reasoning_effort="low" -C "$PWD" --skip-git-repo-check -s workspace-write $REFS -o tmp/codex-$1.txt "Call the built-in image_gen tool exactly once with the prompt below, verbatim, using the attached photos as product references. Do not rewrite the prompt, do not generate variants, do not inspect or edit the result. Save the image as $K/scenes/$1.png and reply with only the saved file path. PROMPT: $2" < /dev/null > tmp/codex-$1.log 2>&1; }

run flatlay "$STYLE Top-down flat lay on a dark woven carbon-fibre surface. The eyeglasses lie open in the centre, slightly angled, temples unfolded so the yellow tips show. Upper left, the black quilted Ferrari pouch lies diagonally. Lower right, the Varilux XR booklet with the blue Varilux card and the navy warranty card fanned on top of it. A single warm yellow light streak rakes across the carbon from the right, echoing the yellow temple tips; everything else deep black and charcoal. Neat, premium, everything clearly visible, generous spacing between items. $KEEP" &
run pouch "$STYLE Close-up three-quarter view at table height: the eyeglasses rest on top of the black quilted Ferrari pouch, the yellow shield on the pouch and the yellow shield on the temple both clearly visible. Behind them, softly out of focus on a dark matte surface, the Varilux XR booklet standing at an angle with the blue Varilux card and the navy warranty card leaning against it. Low warm yellow rim light from behind, deep black background. $KEEP" &
run giftbox "$STYLE Three-quarter top view of an open matte black presentation gift box with a black velvet lining and fitted compartments, on a dark charcoal surface. The eyeglasses sit open in the large centre compartment; the black quilted Ferrari pouch lies folded in a side compartment; the Varilux XR booklet, the blue Varilux card and the navy warranty card sit in a slim compartment along the front edge. The open black lid leans behind. Soft top light, a thin yellow accent light on the box edge. Luxurious gift-set feeling. $KEEP" &
run pitlane "$STYLE Inside a dark racing pit garage at night: the eyeglasses rest on the flat top of a black steel tool chest, temples open, a racing steering wheel with carbon grips lying beside them out of the way. Next to the glasses on the tool chest, a small tidy row: the black quilted Ferrari pouch, the Varilux XR booklet, the blue Varilux card and the navy warranty card. Background out of focus: a glossy dark race car nose, yellow garage lights and bokeh. Palette: black, carbon, warm yellow light. $KEEP" &
wait
